// Deployment settings come from LEADS_* environment variables (see .env.example).
const env = (k, fallback = '') => String($env[k] ?? '').trim() || fallback;
const settings = {
  business_name: env('LEADS_BUSINESS_NAME', 'Palm Grove Realty'),
  supabase_url: env('LEADS_SUPABASE_URL', 'https://YOUR-PROJECT.supabase.co').replace(/\/+$/, ''),
  telegram_sales_chat_id: env('LEADS_SALES_CHAT_ID'),
  telegram_ops_chat_id: env('LEADS_OPS_CHAT_ID'),
  email_from: env('LEADS_EMAIL_FROM'),
  email_reply_to: env('LEADS_EMAIL_REPLY_TO'),
  default_country_code: env('LEADS_DEFAULT_COUNTRY_CODE', '971'),

};
const j = $input.first().json;
const from_webhook = 'webhookUrl' in j;
const req = from_webhook ? { ...(j.query || {}), ...(j.body && typeof j.body === 'object' ? j.body : {}) } : {};

// No sender (the public demo leaves LEADS_EMAIL_FROM empty on purpose): claim nothing, send nothing, finish cleanly.
const skipped = settings.email_from ? '' : 'no_sender';
const max_leads = Math.min(Math.max(parseInt(req.max_leads, 10) || 20, 1), 50);
return [{ json: { from_webhook, settings, max_leads, skipped } }];

const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
function firstName(name) {
  const first = String(name || '').trim().split(/\s+/)[0] || '';
  return /^[\p{L}][\p{L}'.-]{0,29}$/u.test(first) ? first : '';
}
function buildEmail(lang, paragraphs, subject) {
  const text = paragraphs.join('\n\n');
  const dir = lang === 'ar' ? 'rtl' : 'ltr';
  const html = `<div dir="${dir}" lang="${lang}" style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.6;color:#1f2937">`
    + paragraphs.map((p) => `<p>${esc(p).replace(/\n/g, '<br>')}</p>`).join('') + '</div>';
  return { subject: subject.replace(/[\r\n]+/g, ' '), text, html };
}

function followUp(lang, name, business) {
  const first = firstName(name);
  if (lang === 'ar') {
    return buildEmail('ar', [
      first ? `مرحباً ${first}،` : 'مرحباً،',
      `تواصلت مع ${business} مؤخراً بخصوص البحث عن عقار، ونود التأكد من حصولك على المساعدة التي تحتاجها.`,
      'إذا كنت لا تزال تبحث، يمكنك الرد على هذا البريد مع الوقت المناسب للاتصال بك، وسيتواصل معك أحد مستشارينا.',
      `مع أطيب التحيات،\n${business}`,
    ], `متابعة لطلبك لدى ${business}`);
  }
  return buildEmail('en', [
    first ? `Hi ${first},` : 'Hi,',
    `You recently contacted ${business} about finding a property, and we wanted to make sure you got the help you need.`,
    'If you are still looking, reply to this email with a good time to call and an advisor will get back to you.',
    `Kind regards,\n${business}`,
  ], `Following up on your enquiry with ${business}`);
}

const run = $('Prepare run').first().json;
const s = run.settings;
const leads = $input.all().map((i) => i.json).filter((l) => l && l.id && l.email);
if (!leads.length) return [{ json: { none: true } }];
return leads.map((l) => ({ json: {
  lead_id: l.id, language: l.language === 'ar' ? 'ar' : 'en', email_to: l.email,
  email_from: s.email_from, reply_to: s.email_reply_to,
  ...followUp(l.language === 'ar' ? 'ar' : 'en', l.name, s.business_name),
} }));

// One output item per email, in the same order as the leads that went in.
const sent = $input.all();
const leads = $('Build follow-ups').all();
const results = leads.map((lead, i) => {
  const r = sent[i]?.json || {};
  const failed = Boolean(r.error) || (Array.isArray(r.rejected) && r.rejected.length > 0);
  return failed
    ? { lead_id: lead.json.lead_id, ok: false, error: String(r.error?.message || JSON.stringify(r.error || r.rejected)).slice(0, 300) }
    : { lead_id: lead.json.lead_id, ok: true, message_id: r.messageId ?? null };
});
return [{ json: { results } }];

const run = $('Prepare run').first().json;
if (run.skipped) return [{ json: { ok: true, claimed: 0, sent: 0, failed: 0, skipped: run.skipped, from_webhook: run.from_webhook } }];
if (!$('Follow-up results').isExecuted) return [{ json: { ok: true, claimed: 0, sent: 0, failed: 0, from_webhook: run.from_webhook } }];
const results = $('Follow-up results').first().json.results;
const sent = results.filter((r) => r.ok).length;
return [{ json: { ok: true, claimed: results.length, sent, failed: results.length - sent, from_webhook: run.from_webhook } }];
